// magicraft-core compiled to wasm (crates/core-wasm → ./pkg, generated by
// `pnpm -C app build:wasm` and committed). The browser loads it with `loadCore()` (Vite
// serves `pkg/core_bg.wasm` as an asset); Vitest initializes it synchronously from the file
// (`src/wasm/setup.node.ts`). Every other function here needs one of those first.
import init, * as pkg from "./pkg/core.js";

let loading: Promise<void> | null = null;
let ready = false;

/** Loads the wasm module once (browser: fetches the asset). */
export function loadCore(): Promise<void> {
  loading ??= init().then(() => {
    ready = true;
  });
  return loading;
}

/** Synchronous init from the module bytes (Node / tests). */
export function initCoreSync(bytes: BufferSource) {
  if (ready) return;
  pkg.initSync({ module: bytes });
  ready = true;
}

export const coreReady = () => ready;

function need() {
  if (!ready) throw new Error("magicraft core wasm is not loaded (loadCore())");
}

/** `physics::MoveError` names by wasm result code (`1 + discriminant`). */
export const MOVE_ERRORS = ["", "MoveTooFast", "Collision", "NotOnGround", "Flying", "InvalidMoveState", "TimeSkew"] as const;
export type MoveErrorName = Exclude<(typeof MOVE_ERRORS)[number], "">;

export const MOVE_STATE_BYTES = 72;
export const CHUNK_BYTES = 16_384;

export type CheckResult =
  | { ok: true; fallDamage: number; state: Uint8Array }
  | { ok: false; error: MoveErrorName | "BadInput" };

/** Block window for `checkMove`: origin + 4 slots `(cx0,cz0)`, `(cx0+1,cz0)`,
 *  `(cx0,cz0+1)`, `(cx0+1,cz0+1)`; a null slot reads as Stone (not passed to the program). */
export type Quad = { cx0: number; cz0: number; slots: (Uint8Array | null)[] };

/** What the wasm-side window holds (slot arrays by identity), or null = unknown. */
let uploaded: { cx0: number; cz0: number; slots: (Uint8Array | null)[] } | null = null;
let uploads = 0;

/** Forgets the uploaded window (call when chunk bytes may have changed in place; the sync
 *  layer calls it once per decision). */
export function invalidateQuad() {
  uploaded = null;
}

/** Number of chunk uploads to wasm so far (stats / tests). */
export const quadUploads = () => uploads;

/** `physics::check_move` (exactly the program's). Times in chain ms. The window's chunks
 *  are copied into wasm memory only when they differ (by identity) from the last call's. */
export function checkMove(
  params: Uint8Array,
  prev: Uint8Array,
  pos: readonly number[],
  vel: readonly number[],
  onGround: boolean,
  clientMs: number,
  chainMs: number,
  quad: Quad,
): CheckResult {
  need();
  let mask = 0;
  const same = uploaded && uploaded.cx0 === quad.cx0 && uploaded.cz0 === quad.cz0;
  quad.slots.forEach((s, i) => {
    if (!s) return;
    mask |= 1 << i;
    if (same && uploaded!.slots[i] === s) return;
    if (!pkg.set_quad_slot(i, s)) throw new Error("bad chunk length");
    uploads++;
  });
  uploaded = { cx0: quad.cx0, cz0: quad.cz0, slots: [...quad.slots] };
  const r = pkg.check_move_stored(
    params,
    prev,
    Int32Array.from(pos),
    Int32Array.from(vel),
    onGround,
    Math.floor(clientMs),
    Math.floor(chainMs),
    quad.cx0,
    quad.cz0,
    mask,
  );
  if (r[0] === 0) return { ok: true, fallDamage: r[1], state: r.slice(2) };
  return { ok: false, error: r[0] === 255 ? "BadInput" : (MOVE_ERRORS[r[0]] as MoveErrorName) };
}

/** FNV-1a 64 of the sources the wasm was built from (see crates/core-wasm/build.rs). */
export const coreSrcHash = () => (need(), pkg.core_src_hash());

/** `[HALF_W, FEET_EPS, BODY_H, GROUND_HALF_W, GROUND_EPS, LEAD_MS, LAG_MS]` of `physics`. */
export const physicsConstants = () => (need(), [...pkg.physics_constants()]);

/** `physics::move_window(a, b)` (FP positions), or null if it spans more than 2×2 chunks. */
export function coreMoveWindow(a: readonly number[], b: readonly number[]): [number, number] | null {
  need();
  const r = pkg.move_window(Int32Array.from(a), Int32Array.from(b));
  return r.length === 2 ? [r[0], r[1]] : null;
}

/** `blocks::BLOCK_FLAGS` (bit 1 solid, 2 transparent, 4 fluid). */
export function blockFlags(): Uint8Array {
  need();
  return pkg.block_flags();
}

/** `WorldParams::default()` bytes. */
export function defaultParamsBytes(): Uint8Array {
  need();
  return pkg.default_params();
}

/** `WorldParams::validate`: −1 valid, else the `ParamError` discriminant. */
export function validateParamsBytes(b: Uint8Array): number {
  need();
  return pkg.validate_params(b);
}

/** `MoveState::spawn(pos, nowMs)` bytes (optionally on ground). */
export function spawnState(pos: readonly number[], nowMs: number, onGround = false): Uint8Array {
  need();
  return pkg.spawn_state(Int32Array.from(pos), nowMs, onGround);
}

export const coreVersion = () => (need(), pkg.core_version());

// ---------------------------------------------------------------- items / blocks / recipes

/** `blocks::break_time_ms(block, tool of item)` in ms; 0 = not breakable. `item` 0 = hand. */
export function breakTimeMs(block: number, item: number): number {
  need();
  return pkg.break_time_ms(block, item);
}

/** `blocks::can_harvest(block, tool of item)`. */
export function canHarvest(block: number, item: number): boolean {
  need();
  return pkg.can_harvest(block, item);
}

/** `blocks::drop_item(block)` → `[item, count]`, or null. */
export function dropItem(block: number): [number, number] | null {
  need();
  const r = pkg.drop_item(block);
  return r.length === 2 ? [r[0], r[1]] : null;
}

/** Item properties from the core (`items::Item`). */
export type CoreItem = {
  id: number;
  /** Block placed by the item, or −1. */
  block: number;
  /** Tool kind (0 pickaxe, 1 axe, 2 shovel, 3 sword), or −1. */
  toolKind: number;
  /** Tool tier 1..4 (wood..diamond), 0 for non-tools. */
  tier: number;
  /** Attack damage (1 = fist for non-tools). */
  damage: number;
  maxStack: number;
  maxDurability: number;
  /** Food points, or −1 if not edible. */
  food: number;
};

/** Every item of the core with its properties (cached). */
let itemCache: Map<number, CoreItem> | null = null;
export function coreItems(): Map<number, CoreItem> {
  need();
  if (itemCache) return itemCache;
  itemCache = new Map();
  for (const id of pkg.item_ids()) {
    const [block, toolKind, tier, damage, maxStack, maxDurability, food] = pkg.item_info(id);
    itemCache.set(id, { id, block, toolKind, tier, damage, maxStack, maxDurability, food });
  }
  return itemCache;
}

/** One `recipes::RECIPES` entry; `id` = its index (what `craft` takes). */
export type CoreRecipe = {
  id: number;
  inputs: [item: number, amount: number][];
  output: [item: number, amount: number];
  /** 0 anywhere, 1 crafting table, 2 furnace. */
  station: number;
  /** Fuel units per craft (coal first, then planks). */
  fuel: number;
};

let recipeCache: CoreRecipe[] | null = null;
/** The core's recipe table in id order (cached). */
export function coreRecipes(): CoreRecipe[] {
  need();
  if (recipeCache) return recipeCache;
  const t = pkg.recipe_table();
  const out: CoreRecipe[] = [];
  for (let i = 0; i < t.length; ) {
    const n = t[i++];
    const inputs: [number, number][] = [];
    for (let k = 0; k < n; k++, i += 2) inputs.push([t[i], t[i + 1]]);
    out.push({ id: out.length, inputs, output: [t[i], t[i + 1]], station: t[i + 2], fuel: t[i + 3] });
    i += 4;
  }
  return (recipeCache = out);
}

/** `recipes::CraftError` names by wasm result code (`1 + discriminant`). */
export const CRAFT_ERRORS = ["", "UnknownRecipe", "WrongStation", "MissingInputs", "MissingFuel", "InventoryFull", "InvalidCount"] as const;

/** `recipes::craft` on a copy of the 216 inventory bytes: the inventory after, or the error
 *  (named like the program's errors: `NoSpace` → `InventoryFull`). */
export function simulateCraft(inv: Uint8Array, recipe: number, count: number, table: boolean, furnace: boolean): { ok: true; inv: Uint8Array } | { ok: false; error: string } {
  need();
  const r = pkg.craft(inv, recipe, count, table, furnace);
  if (r[0] === 0) return { ok: true, inv: r.slice(1) };
  return { ok: false, error: r[0] === 255 ? "BadInput" : CRAFT_ERRORS[r[0]] };
}

/** Largest craftable count (0..64) of `recipe` with this inventory and stations. */
export function maxCrafts(inv: Uint8Array, recipe: number, table: boolean, furnace: boolean): number {
  need();
  return pkg.max_crafts(inv, recipe, table, furnace);
}
